#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────


# Sets up the Clerk, Convex and Vercel projects of Arashan, and writes the values to Vercel, to
# GitHub Actions and to apps/web/.env.local. docs/environment.md lists each variable and where it
# goes. Run it from anywhere in the repository: scripts/setup-services.sh

# The wizard's memory: every value it captures, so that a re-run offers it as the default. It is
# git-ignored (.env.*) and only the owner can read it. Delete it when the setup is done.
ENV_FILE=".env.setup.local"
WEB_ENV_FILE="apps/web/.env.local"
VERCEL_CLI="vercel@64.5.0"
VERCEL_PROJECT="arashan"

# ask_valid KEY REGEX "Prompt" "Hint" asks until the value matches REGEX.
ask_valid() {
  local key="$1" regex="$2" prompt="$3" hint="$4"
  while true; do
    ask "$key" "$prompt"
    [[ "${!key}" =~ $regex ]] && return
    warn "$hint"
  done
}

# ask_secret_valid KEY REGEX "Prompt" "Hint" is ask_valid with hidden input.
ask_secret_valid() {
  local key="$1" regex="$2" prompt="$3" hint="$4"
  while true; do
    ask_secret "$key" "$prompt"
    [[ "${!key}" =~ $regex ]] && return
    warn "$hint"
  done
}

# vercel ARGS... runs the pinned Vercel CLI with the captured token.
vercel() { vp dlx -s "$VERCEL_CLI" "$@" --token="$VERCEL_TOKEN"; }

# vercel_env NAME TARGET VALUE adds or replaces a plain (non-sensitive) Vercel variable. The
# GitHub Actions build pulls it with `vercel pull`, which gets no values of sensitive variables.
vercel_env() {
  if printf '%s' "$3" | vercel env add "$1" "$2" --no-sensitive --force --yes >/dev/null 2>&1; then
    printf '  %s✓ set%s Vercel %s variable %s\n' "$GREEN" "$RESET" "$2" "$1"
  else
    SKIPPED+=("Vercel $2 variable $1 (Project → Settings → Environment Variables)")
    warn "could not set the Vercel $2 variable $1; add it in the dashboard"
  fi
}

run_wizard() {

TOTAL_STAGES=10

cd "$(git rev-parse --show-toplevel)"

banner "Arashan: Clerk, Convex and Vercel setup"

stage "Clerk: make the application"
say "Clerk identifies the Users: a username and a password, and the email is optional."
open_url "https://dashboard.clerk.com/apps/new"
step "Application name: Arashan."
step "Sign-in options: turn on Username. Turn off Email, Phone and all social providers."
step "Click 'Create application'. Skip the framework quickstart page."
pause "Press Enter when the application exists."

stage "Clerk: username, password, optional email"
say "Make sure that the sign-up asks for a username and a password only."
open_url "https://dashboard.clerk.com/last-active?path=user-authentication/email-phone-username"
note "The page is Configure → User & authentication. The labels can be a little different."
step "Username: on, and required to sign up."
step "Email address: on for the profile, but not required to sign up. No email verification step."
step "Phone number: off."
step "Password: on (the 'Password' tab or section). Keep the default password rules."
step "Save each section that has a Save button."
pause "Press Enter when the settings are saved."

stage "Clerk: connect Convex"
say "Convex accepts the Clerk session token when the Convex integration is on."
open_url "https://dashboard.clerk.com/apps/setup/convex"
step "Select the Arashan application if Clerk asks, then click 'Activate Convex integration'."
step "Copy the Frontend API URL that the page shows (https://<words>.clerk.accounts.dev)."
ask_valid CLERK_JWT_ISSUER_DOMAIN '^https://[^/[:space:]]+$' "Paste the Frontend API URL:" \
  "Expected https://<host> with no path and no trailing slash."
write_env CLERK_JWT_ISSUER_DOMAIN "$CLERK_JWT_ISSUER_DOMAIN"

stage "Clerk: API keys"
open_url "https://dashboard.clerk.com/last-active?path=api-keys"
step "Copy the Publishable key (pk_test_...)."
ask_valid VITE_CLERK_PUBLISHABLE_KEY '^pk_(test|live)_[A-Za-z0-9+/=_-]+$' "Paste the publishable key:" \
  "A publishable key starts with pk_test_ or pk_live_."
write_env VITE_CLERK_PUBLISHABLE_KEY "$VITE_CLERK_PUBLISHABLE_KEY"
step "Copy the Secret key (sk_test_...)."
ask_secret_valid CLERK_SECRET_KEY '^sk_(test|live)_[A-Za-z0-9]+$' "Paste the secret key (hidden):" \
  "A secret key starts with sk_test_ or sk_live_."
write_env CLERK_SECRET_KEY "$CLERK_SECRET_KEY"

stage "Convex: the project and its development deployment"
open_url "https://dashboard.convex.dev"
step "Click 'Create Project' and name it arashan."
step "In the deployment menu at the top, select Development (create it if the dashboard asks)."
step "Open Settings. Copy the Deployment URL (https://<name>.convex.cloud, not .convex.site)."
ask_valid CONVEX_DEV_URL '^https://[a-z0-9-]+\.convex\.cloud$' "Paste the development Deployment URL:" \
  "Expected https://<name>.convex.cloud."
write_env CONVEX_DEV_URL "$CONVEX_DEV_URL"
step "Open Settings → Environment Variables and add these two variables:"
note "    CLERK_JWT_ISSUER_DOMAIN = $CLERK_JWT_ISSUER_DOMAIN"
note "    CLERK_SECRET_KEY        = the Clerk secret key (sk_test_...)"
pause "Press Enter when the development deployment has both variables."

stage "Convex: the production deployment and its deploy key"
step "In the deployment menu at the top, select Production (create it if the dashboard asks)."
step "Open Settings. Copy the Deployment URL (https://<name>.convex.cloud)."
ask_valid CONVEX_PROD_URL '^https://[a-z0-9-]+\.convex\.cloud$' "Paste the production Deployment URL:" \
  "Expected https://<name>.convex.cloud."
write_env CONVEX_PROD_URL "$CONVEX_PROD_URL"
step "Open Settings → Environment Variables and add the same two variables:"
note "    CLERK_JWT_ISSUER_DOMAIN = $CLERK_JWT_ISSUER_DOMAIN"
note "    CLERK_SECRET_KEY        = the Clerk secret key (sk_test_...)"
pause "Press Enter when the production deployment has both variables."
step "In Settings, click 'Generate Production Deploy Key'. Name it github-actions. Copy it."
ask_secret_valid CONVEX_DEPLOY_KEY '^prod:.+' "Paste the production deploy key (hidden):" \
  "A production deploy key starts with prod:."
write_env CONVEX_DEPLOY_KEY "$CONVEX_DEPLOY_KEY"

stage "Vercel: an access token"
say "GitHub Actions builds the app and deploys it to Vercel with this token."
open_url "https://vercel.com/account/settings/tokens"
step "Click 'Create Token'. Name: arashan-github-actions."
step "Scope: the team that will own the project. Expiration: the longest that you accept."
ask_secret_valid VERCEL_TOKEN '^[A-Za-z0-9_-]{20,}$' "Paste the token (hidden):" \
  "That does not look like a Vercel token."
write_env VERCEL_TOKEN "$VERCEL_TOKEN"

stage "Vercel: the project"
say "The wizard makes the Vercel project '$VERCEL_PROJECT' with the CLI and links this checkout to it."
note "The first CLI run can take a minute: vp downloads $VERCEL_CLI."
if confirm "Make or link the Vercel project '$VERCEL_PROJECT' now?"; then
  vercel project add "$VERCEL_PROJECT" >/dev/null 2>&1 || note "The project exists already."
  vercel link --yes --project "$VERCEL_PROJECT" >/dev/null ||
    warn "vercel link failed: run 'vp dlx $VERCEL_CLI link --project $VERCEL_PROJECT' and re-run the wizard"
  # Vercel's builders cannot build this repository (docs/environment.md), so no Git connection:
  # the Deploy workflow deploys each pull request and each push to main.
  vercel git disconnect --yes >/dev/null 2>&1 || true
fi
if [[ -f .vercel/project.json ]]; then
  VERCEL_ORG_ID=$(node -p 'require("./.vercel/project.json").orgId')
  VERCEL_PROJECT_ID=$(node -p 'require("./.vercel/project.json").projectId')
  write_env VERCEL_ORG_ID "$VERCEL_ORG_ID"
  write_env VERCEL_PROJECT_ID "$VERCEL_PROJECT_ID"
else
  SKIPPED+=("the Vercel project, its variables and the GitHub variables VERCEL_ORG_ID, VERCEL_PROJECT_ID")
fi

stage "Vercel: environment variables"
if [[ -f .vercel/project.json ]]; then
  say "Production uses the production Convex deployment. Previews use the development one."
  vercel_env VITE_CONVEX_URL production "$CONVEX_PROD_URL"
  vercel_env VITE_CONVEX_URL preview "$CONVEX_DEV_URL"
  vercel_env VITE_CLERK_PUBLISHABLE_KEY production "$VITE_CLERK_PUBLISHABLE_KEY"
  vercel_env VITE_CLERK_PUBLISHABLE_KEY preview "$VITE_CLERK_PUBLISHABLE_KEY"
else
  warn "The checkout is not linked to a Vercel project, so the wizard skips this stage."
fi
pause

stage "GitHub Actions: secrets and variables, and the local env file"
say "Secrets: CONVEX_DEPLOY_KEY, CLERK_SECRET_KEY, VERCEL_TOKEN."
say "Variables: VITE_CLERK_PUBLISHABLE_KEY, CLERK_JWT_ISSUER_DOMAIN, VERCEL_ORG_ID, VERCEL_PROJECT_ID."
if confirm "Write them to the GitHub repository now (replaces existing values)?"; then
  set_secret CONVEX_DEPLOY_KEY "$CONVEX_DEPLOY_KEY"
  set_secret CLERK_SECRET_KEY "$CLERK_SECRET_KEY"
  set_secret VERCEL_TOKEN "$VERCEL_TOKEN"
  set_var VITE_CLERK_PUBLISHABLE_KEY "$VITE_CLERK_PUBLISHABLE_KEY"
  set_var CLERK_JWT_ISSUER_DOMAIN "$CLERK_JWT_ISSUER_DOMAIN"
  if [[ -n "${VERCEL_ORG_ID:-}" ]]; then
    set_var VERCEL_ORG_ID "$VERCEL_ORG_ID"
    set_var VERCEL_PROJECT_ID "$VERCEL_PROJECT_ID"
  fi
else
  SKIPPED+=("the GitHub Actions secrets and variables")
fi
# Vite reads env files from the app's root. Only the public key goes there.
ENV_FILE="$WEB_ENV_FILE" write_env VITE_CLERK_PUBLISHABLE_KEY "$VITE_CLERK_PUBLISHABLE_KEY"
pause

finish
note "Delete .env.setup.local when you do not need to re-run the wizard: it has the secrets."
}

run_wizard "$@"; exit
